--progressnote
update
    progressnote
set
    description = '<p>This worker met with Ms. Richards and Mr. Bradley at their home for an unscheduled visit. When this worker arrived, this worker observed Mr. Bradley burning trash and a large trash dumpster. This worker met with Mr. Bradley who stated that Ms. Richards was inside the home with her mother cleaning the house. Mr. Bradley was outside with his friend, who was also assisting in cleaning the home. Mr. Bradley stated that Ms. Richards plans to sell the home and move back to Salisbury. This worker went inside the home and observed the all the clutter in the home had been disposed of and the carpet had also been removed. The home had drastic improvement. This worker praised Ms. Richards on the work done in the home. </p><p>Jakye and Dakota were not at the home and are still living with a relative. This worker encouraged Ms. Richards and Mr. Bradley to continue with their progress. This worker will follow up with the family in a week.&nbsp;</p>'
where
    progressnoteid = '95d57338-b5ba-40b6-b45c-e1a4805fe75a'
    and progressnotetypeid = '786495b2-c779-4cc4-b812-6a8439bfa96e';

